import numpy as np
import itertools

def f(x, y):
    return 3*x**2 + 3*y**2 - x**2 * y**2 - 8*x*y - 1

def solve(n):
    points = np.linspace(0.01, 10, 200)
    for combo in itertools.combinations(points, n):
        valid = True
        for i in range(n):
            for j in range(i + 1, n):
                if f(combo[i], combo[j]) < 0:
                    valid = False
                    break
            if not valid: break
        if valid:
            return combo
    return None

print(f"n=3: {solve(3)}")
print(f"n=4: {solve(4)}")

